const payload = $json.body || $json;
const message = String(payload.message || payload.mensaje || payload.text || "").trim();
const bot = payload.bot || {};
const knowledge = String(bot.knowledge || "");
const businessName = bot.businessName || bot.name || "Denin Camisetas";
const tone = bot.tone || "profesional";

function normalize(value) {
  return String(value || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

function money(value) {
  return new Intl.NumberFormat("es-CO").format(value) + " COP";
}

const catalog = [
  { name: "Basica algodon 100%", price: 39900, quality: "algodon suave, fresca y no transparenta" },
  { name: "Oversize pesada 240 g", price: 59900, quality: "tela gruesa, caida amplia y costura reforzada" },
  { name: "Premium cuello reforzado", price: 69900, quality: "acabado premium, cuello firme y mayor durabilidad" },
];

const aliases = [
  { intent: "precio", question: /(precio|cuanto|cuesta|valor|vale|cotiza|catalogo)/, field: /(precio|valor|costo|cop|\$|[0-9][0-9.,]+)/ },
  { intent: "ubicacion", question: /(ubicacion|ubicados|donde|direccion|sede|local|barrio)/, field: /(ubicacion|direccion|sede|local|ciudad|barrio|punto)/ },
  { intent: "productos", question: /(producto|productos|camisa|camisas|tiene|tienen|vende|venden|disponible|disponibles|referencia|modelo|catalogo)/, field: /(producto|productos|camisa|camisas|catalogo|disponib|stock|referencia|modelo|talla|color)/ },
  { intent: "envios", question: /(envio|envios|domicilio|entrega|pais|ciudad|transportadora)/, field: /(envio|envios|domicilio|entrega|transportadora|pais|ciudad)/ },
  { intent: "pagos", question: /(pago|pagos|pagar|pagas|paga|abono|abonar|contra|contraentrega|nequi|daviplata|transferencia|efectivo)/, field: /(pago|pagos|contra|contraentrega|nequi|daviplata|transferencia|efectivo)/ },
  { intent: "calidad", question: /(calidad|tela|material|algodon|garantia|marca|costura)/, field: /(calidad|tela|material|algodon|garantia|marca|costura|premium)/ },
  { intent: "horarios", question: /(horario|hora|abren|cierran|atienden|atencion)/, field: /(horario|hora|atencion|abren|cierran|lunes|sabado|domingo)/ },
  { intent: "compra", question: /(comprar|quiero|pedido|orden|separar|me interesa)/, field: /(compra|pedido|orden|separar|datos)/ },
];

const stopWords = new Set(["que", "cual", "cuales", "como", "donde", "estan", "esta", "tiene", "tienen", "hay", "los", "las", "una", "unos", "para", "por", "del", "con", "me", "mi", "su", "sus", "son", "es"]);

function knowledgeFields() {
  const fields = [];
  for (const rawLine of knowledge.split(/\n+/)) {
    const line = rawLine.trim();
    if (!line) continue;
    const index = line.indexOf(":");
    if (index > 0) {
      const title = line.slice(0, index).trim();
      const value = line.slice(index + 1).trim();
      if (value) fields.push({ title, value, raw: line });
    } else {
      fields.push({ title: "Informacion", value: line, raw: line });
    }
  }
  return fields;
}

function detectIntent(text) {
  const lower = normalize(text);
  const match = aliases.find((item) => item.question.test(lower));
  return match ? match.intent : "general";
}

function scoreField(field, lowerMessage) {
  const title = normalize(field.title);
  const value = normalize(field.value);
  let score = 0;

  for (const alias of aliases) {
    if (alias.question.test(lowerMessage) && alias.field.test(title)) score += 20;
    if (alias.question.test(lowerMessage) && alias.field.test(value)) score += 4;
  }

  const tokens = lowerMessage.split(/[^a-z0-9]+/).filter((token) => token.length > 2 && !stopWords.has(token));
  for (const token of tokens) {
    if (title === token) score += 30;
    else if (title.includes(token)) score += 12;
    if (value.includes(token)) score += 2;
  }

  return score;
}

function bestKnowledgeMatch(text) {
  const lower = normalize(text);
  const fields = knowledgeFields();
  let best = null;
  for (const field of fields) {
    const score = scoreField(field, lower);
    if (score > 0 && (!best || score > best.score)) best = { ...field, score };
  }
  return best;
}

function availableTopics() {
  return knowledgeFields().map((field) => field.title).filter(Boolean).slice(0, 8).join(", ");
}

function style(text) {
  if (tone === "cercano") return text.replace(/^Hola\. /, "Hola, que mas. ");
  if (tone === "premium") return text + " Te puedo orientar con una recomendacion segun el uso que buscas.";
  return text;
}

function salesClose(intent) {
  if (intent === "precio") return " Si quieres, te ayudo a elegir la mejor opcion y te confirmo el pedido con producto, cantidad y ciudad.";
  if (intent === "pagos") return " Si te interesa, dime que producto quieres y te guio para dejar el pedido listo.";
  if (intent === "envios") return " Para avanzar, dime tu ciudad y el producto que te gusto para confirmarte total y entrega.";
  if (intent === "productos") return " Si alguno te interesa, dime cual quieres, cantidad y ciudad y te ayudo a completar la compra.";
  if (intent === "ubicacion") return " Tambien puedo ayudarte por aqui a elegir el producto antes de que compres.";
  if (intent === "calidad") return " Si buscas una recomendacion, dime para que uso la quieres y te sugiero la mejor opcion.";
  return " Si quieres comprar, dime que producto te interesa y te ayudo con el siguiente paso.";
}

function relevantExcerpt(value, intent) {
  const text = String(value || "").trim();
  if (text.length <= 700) return text;
  const intentWords = {
    precio: /precio|precios|valor|costo|tarifa|plan|cop|\$/,
    pagos: /pago|pagos|pagar|nequi|daviplata|transferencia|contra|efectivo/,
    envios: /envio|envios|entrega|domicilio|transportadora|ciudad|pais/,
    productos: /producto|productos|servicio|servicios|catalogo|camisa|menu|disponible/,
    ubicacion: /ubicacion|direccion|sede|local|ciudad|barrio/,
    calidad: /calidad|garantia|material|tela|marca|premium/,
  };
  const matcher = intentWords[intent] || /producto|servicio|precio|pago|envio|compra|objetivo/;
  const sentences = text.split(/(?<=[.!?])\s+|\n+/).map((item) => item.trim()).filter(Boolean);
  const selected = sentences.filter((sentence) => matcher.test(normalize(sentence))).slice(0, 5);
  const excerpt = (selected.length ? selected : sentences.slice(0, 4)).join(" ");
  return excerpt.length > 900 ? excerpt.slice(0, 900).trim() + "..." : excerpt;
}

function naturalFieldReply(field, intent) {
  const value = relevantExcerpt(field.value || field.raw || "", intent);
  if (!value) return "Te ayudo con gusto. Dime que producto te interesa y te doy la informacion disponible.";
  const finalValue = /[.!?]$/.test(value) ? value : value + ".";
  return style(finalValue + salesClose(intent));
}

function responseFor(intent) {
  if (!message) {
    return {
      reply: "No recibi un mensaje. Escribeme una pregunta sobre el negocio o sus productos.",
      lead_status: "sin_mensaje",
    };
  }

  const dynamicMatch = bestKnowledgeMatch(message);
  if (dynamicMatch && dynamicMatch.score >= 4) {
    return {
      reply: naturalFieldReply(dynamicMatch, intent),
      lead_status: intent === "precio" ? "cotizando" : "informado",
    };
  }

  if (intent === "precio") {
    return {
      reply: style(
        "Hola. Estos son los precios de " + businessName + ":\n" +
          catalog.map((item) => "- " + item.name + ": " + money(item.price)).join("\n") +
          "\n\nSi me dices talla, color y cantidad, te confirmo disponibilidad y total."
      ),
      lead_status: "cotizando",
    };
  }

  if (intent === "envios") {
    return {
      reply: style("Hacemos envios segun la ciudad. Dime tu ciudad y el producto que te gusto para confirmarte costo, tiempo de entrega y total del pedido."),
      lead_status: "informado",
    };
  }

  if (intent === "pagos") {
    return {
      reply: style("Puedes pagar por los metodos configurados por la empresa. Dime producto, ciudad y cantidad para guiarte y dejar el pedido listo."),
      lead_status: "pago_consultado",
    };
  }

  if (intent === "calidad") {
    return {
      reply: style("Te puedo orientar por calidad, material y garantia segun lo que busques. Dime la referencia o el uso que le vas a dar y te recomiendo la mejor opcion."),
      lead_status: "calidad_consultada",
    };
  }

  if (intent === "productos") {
    const topics = availableTopics();
    return {
      reply: style(topics ? "Puedo ayudarte con " + topics + ". Dime que producto te interesa y te doy una recomendacion para que elijas bien." : "Dime que producto buscas y te ayudo a escoger la mejor opcion disponible."),
      lead_status: "calificando",
    };
  }

  if (intent === "compra") {
    return {
      reply: style("Perfecto. Para armar tu pedido necesito nombre, ciudad, producto, cantidad y metodo de pago."),
      lead_status: "lead_caliente",
    };
  }

  const topics = availableTopics();
  return {
    reply: style(
      topics
        ? "Hola. Soy el asistente de " + businessName + ". Puedo ayudarte con " + topics + ". Cuentame que necesitas y te guio para escoger o comprar."
        : "Hola. Soy el asistente de " + businessName + ". Te puedo ayudar con precios, calidad, envios, pagos y disponibilidad. Que te gustaria saber?"
    ),
    lead_status: "nuevo",
  };
}

const intent = detectIntent(message);
const fallback = responseFor(intent);
return [
  {
    json: {
      ok: true,
      source: "n8n",
      bot: { name: bot.name || "Denin Camisetas", businessName, tone, knowledge },
      message,
      conversation: Array.isArray(payload.conversation) ? payload.conversation.slice(-8) : [],
      intent,
      fallbackReply: fallback.reply,
      lead_status: fallback.lead_status,
      reusable: true,
      knowledge_used: knowledge ? "frontend_bot_config" : "default_catalog",
      aiRequest: {
        message,
        bot: { name: bot.name || "Denin Camisetas", businessName, tone, knowledge },
        conversation: Array.isArray(payload.conversation) ? payload.conversation.slice(-8) : [],
        intent,
        lead_status: fallback.lead_status,
        fallbackReply: fallback.reply
      }
    },
  },
];

const prepared = $("Preparar Contexto").first().json;
const ai = $json || {};
const hasAiReply = ai.ok === true && typeof ai.reply === "string" && ai.reply.trim();

function normalize(value) {
  return String(value || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

function isGeneric(reply) {
  const text = normalize(reply);
  return /soy el asistente/.test(text) && /te puedo ayudar/.test(text) && /(precios|calidad|envios|pagos|disponibilidad)/.test(text);
}

const aiReply = hasAiReply ? ai.reply : "";
const useFallback = !hasAiReply || (prepared.fallbackReply && isGeneric(aiReply) && !isGeneric(prepared.fallbackReply));

return [
  {
    json: {
      ok: true,
      source: useFallback ? "n8n" : "openai+n8n",
      bot: prepared.bot,
      message: prepared.message,
      intent: useFallback ? prepared.intent : (ai.intent || prepared.intent),
      reply: useFallback ? prepared.fallbackReply : ai.reply,
      lead_status: useFallback ? prepared.lead_status : (ai.lead_status || prepared.lead_status),
      needs_human: Boolean(ai.needs_human),
      reusable: true,
      received_at: new Date().toISOString(),
      knowledge_used: prepared.knowledge_used,
      openai_model: ai.model || null,
      fallback_used: useFallback
    },
  },
];
